insert into public.sb_problems (id,code,lesson,order_index,problem_type,title,prompt,grid_width,grid_depth,max_height,given_blocks,start_blocks,given,choices,answer,grading_mode,hint,explanation,difficulty,xp) values ('2bed5ce1-053e-42f1-8cb7-2808175a9407','L3-01',3,1,'PROJECTION_DRAW','위에서 본 모양 그리기','이 모양을 위에서 본 모양을 오른쪽 격자에 그려 보세요.',3,3,3,'[{"x":0,"y":0,"z":0},{"x":1,"y":0,"z":0},{"x":2,"y":0,"z":0},{"x":0,"y":0,"z":1},{"x":0,"y":1,"z":0},{"x":1,"y":1,"z":0}]'::jsonb,'[]'::jsonb,'{"allowRotate":true,"allowLayerView":true}'::jsonb,'[]'::jsonb,'{"kind":"projections","projections":{"top":[[true,true,true],[true,false,false],[false,false,false]]}}'::jsonb,'exact','[위에서 보기] 버튼을 누르면 확인하기 쉬워요. 높이는 신경 쓰지 않아요.','위에서 본 모양은 쌓기나무가 놓인 ''자리''만 나타냅니다.',1,30) on conflict (id) do nothing;
