insert into public.sb_problems (id,code,lesson,order_index,problem_type,title,prompt,grid_width,grid_depth,max_height,given_blocks,start_blocks,given,choices,answer,grading_mode,hint,explanation,difficulty,xp) values ('abdb3f14-e6e9-4903-8ece-f4a5b83f4ef9','L12-01',12,1,'COUNT','종합 1 - 개수 구하기','이 모양을 만드는 데 쓰인 쌓기나무는 모두 몇 개인가요?',4,4,4,'[{"x":0,"y":0,"z":0},{"x":1,"y":0,"z":0},{"x":2,"y":0,"z":0},{"x":0,"y":0,"z":1},{"x":1,"y":0,"z":1},{"x":2,"y":0,"z":1},{"x":3,"y":0,"z":1},{"x":1,"y":0,"z":2},{"x":2,"y":0,"z":2},{"x":0,"y":1,"z":0},{"x":1,"y":1,"z":0},{"x":1,"y":1,"z":1},{"x":2,"y":1,"z":1},{"x":1,"y":2,"z":0}]'::jsonb,'[]'::jsonb,'{"allowRotate":true,"allowLayerView":true}'::jsonb,'[]'::jsonb,'{"kind":"count","value":14}'::jsonb,'exact','자리별 높이를 더하거나 층별로 나누어 세어 보세요. 두 방법 모두 좋아요.','자리별로 세기와 층별로 세기 중 편한 방법을 쓰면 됩니다.',2,30) on conflict (id) do nothing;
insert into public.sb_problems (id,code,lesson,order_index,problem_type,title,prompt,grid_width,grid_depth,max_height,given_blocks,start_blocks,given,choices,answer,grading_mode,hint,explanation,difficulty,xp) values ('2b43a149-a5dd-442f-8d3f-a6f7f7d3c149','L12-02',12,2,'PROJECTION_DRAW','종합 2 - 세 방향 모양 그리기','이 모양의 위, 앞, 옆에서 본 모양을 모두 그려 보세요.',4,4,4,'[{"x":0,"y":0,"z":0},{"x":1,"y":0,"z":0},{"x":2,"y":0,"z":0},{"x":0,"y":0,"z":1},{"x":1,"y":0,"z":1},{"x":2,"y":0,"z":1},{"x":3,"y":0,"z":1},{"x":1,"y":0,"z":2},{"x":2,"y":0,"z":2},{"x":0,"y":1,"z":0},{"x":1,"y":1,"z":0},{"x":1,"y":1,"z":1},{"x":2,"y":1,"z":1},{"x":1,"y":2,"z":0}]'::jsonb,'[]'::jsonb,'{"allowRotate":true,"allowLayerView":true}'::jsonb,'[]'::jsonb,'{"kind":"projections","projections":{"top":[[true,true,true,false],[true,true,true,true],[false,true,true,false],[false,false,false,false]],"front":[[true,true,true,true],[true,true,true,false],[false,true,false,false],[false,false,false,false]],"side":[[false,true,true,true],[false,false,true,true],[false,false,false,true],[false,false,false,false]]}}'::jsonb,'exact','시점 버튼을 눌러 한 방향씩 확인하며 그리세요.','입체 모양을 세 방향에서 본 모양으로 나타내면 다른 사람에게 정확히 설명할 수 있습니다.',3,30) on conflict (id) do nothing;
insert into public.sb_problems (id,code,lesson,order_index,problem_type,title,prompt,grid_width,grid_depth,max_height,given_blocks,start_blocks,given,choices,answer,grading_mode,hint,explanation,difficulty,xp) values ('fc480148-ae29-4e8b-8049-7ab2c0b0c1a7','L12-03',12,3,'BUILD_FROM_VIEWS','종합 3 - 세 방향 보고 쌓기','아래 세 방향 조건을 만족하는 모양을 쌓아 보세요.',4,4,4,'[]'::jsonb,'[]'::jsonb,'{"projections":{"top":[[true,true,true,false],[true,true,true,true],[false,true,true,false],[false,false,false,false]],"front":[[true,true,true,true],[true,true,true,false],[false,true,false,false],[false,false,false,false]],"side":[[false,true,true,true],[false,false,true,true],[false,false,false,true],[false,false,false,false]]},"allowRotate":true,"allowLayerView":true}'::jsonb,'[]'::jsonb,'{"kind":"projections","projections":{"top":[[true,true,true,false],[true,true,true,true],[false,true,true,false],[false,false,false,false]],"front":[[true,true,true,true],[true,true,true,false],[false,true,false,false],[false,false,false,false]],"side":[[false,true,true,true],[false,false,true,true],[false,false,false,true],[false,false,false,false]]}}'::jsonb,'constraint','위에서 본 모양으로 놓을 자리를 먼저 정하고, 앞·옆 모양에 맞게 높이를 조절하세요.','세 방향에서 본 모양을 모두 만족하면 정답입니다. 이 단원의 마지막 도전이었어요!',3,30) on conflict (id) do nothing;
